// Additional authored parts. All geometry remains cosmetic and uses the shared mounts.
export function extendCatalog(catalog,palettes,emojis,opt){
  emojis.push(...[['panda','🐼','Bamboo express'],['tiger','🐯','Tiger team'],['pig','🐷','Space ham'],['unicorn','🦄','Unicorn'],['chicken','🐔','Chicken run'],['octopus','🐙','Eight arms'],['dog','🐶','Good dog'],['skull','💀','Dead serious'],['sun','🌞','Sun face'],['moonface','🌝','Moon face'],['heartface','😍','Love at first flight'],['nerd','🤓','Mission specialist']].map(([id,glyph,name])=>opt(id,name,'Oddities',{glyph})));
  catalog.cabin.push(...['bridge|Flight bridge','observatory|Observatory','helmet|Pressure helmet','radar|Radar array','lantern|Space lantern|Oddities','castle|Tiny fortress|Oddities'].map(s=>opt(...s.split('|'))),...emojis.slice(12));
  catalog.body.push(...['reactor|Reactor drum','barrel|Ribbed barrel','hex|Hex frame','pizza|Pizza payload|Oddities','burger|Burger module|Oddities','aquarium|Fish tank|Oddities'].map(s=>opt(...s.split('|'))));
  catalog.legs.push(...['piston|Heavy pistons','knee|Articulated knees','tracks|Moon treads','flippers|Flipper feet|Oddities'].map(s=>opt(...s.split('|'))));
  catalog.engine.push(...['triple|Three bells','ring|Ring thruster','trumpet|Brass section|Oddities'].map(s=>opt(...s.split('|'))));
  const colors=[['rust','Rust & cream','#b96f4f','#e4cfa5','#633b2e','#9ddad2'],['forest','Forest service','#789b78','#ddd3b0','#3e5744','#a4d9d2'],['cobalt','Cobalt blue','#668fd8','#d9e0e6','#344d80','#a6ece8'],['crimson','Crimson wing','#c65a67','#e4cec4','#762e46','#a3d9e7'],['copper','Copper age','#c69365','#e5d2b8','#6b4c3d','#b0dedc'],['lemon','Lemon drop','#e5cf64','#f0e8bb','#8c713c','#d0a8db'],['mono','Graphite','#79858b','#c5d0d3','#38454e','#8fe6db'],['candy','Candy store','#e497c9','#d8cdf1','#805b91','#a5e7e1']];
  palettes.push(...colors.map(([id,name,primary,secondary,dark,glass])=>opt(id,name,'',{primary,secondary,dark,glass})));
  catalog.flame.push(...[['ember','Ember','#f18c5d'],['lime','Lime light','#d4ee7d'],['white','White hot','#e9f6ff'],['red','Red alert','#ff6c79']].map(([id,name,color])=>opt(id,name,'',{color})));
  const stickers=[['🛸','UFO'],['☄️','Comet'],['🌍','Earth'],['🌞','Sun'],['❄️','Snowflake'],['🍕','Pizza'],['🍩','Donut'],['🍌','Banana'],['🐸','Frog'],['🐙','Octopus'],['🦖','Dinosaur'],['🦄','Unicorn'],['👑','Crown'],['🎲','Dice'],['🎯','Target'],['🧲','Magnet'],['🧪','Science'],['⚙️','Gear'],['🌻','Sunflower'],['☕','Coffee'],['💯','Hundred'],['🛰️','Satellite'],['🔧','Wrench'],['🎵','Music']];
  catalog.stickers.push(...stickers.map(([glyph,name],i)=>opt(String(i+12),name,'',{glyph})));
  catalog.builds.push(...['surveyor|Polar surveyor','radiotower|Deep-space relay','lifeboat|Rescue pod','industrial|Heavy lifter','stargazer|Stargazer','submarine|Sea of stars','pizzaparty|Pizza party|Oddities','burgerjoint|Drive-through|Oddities','aquanaut|Fish out of water|Oddities','fortress|Pocket fortress|Oddities','moonduck|Lunar chicken|Oddities','candyfloss|Sugar rush|Oddities'].map(s=>opt(...s.split('|'))));
}
export const EXTRA_BUILDS={
 surveyor:{name:'Polar Surveyor',cabin:'helmet',body:'hex',legs:'piston',engine:'triple',palette:'arctic',flame:'white'},
 radiotower:{name:'Deep-space Relay',cabin:'radar',body:'truss',legs:'knee',engine:'ring',palette:'cobalt'},
 lifeboat:{name:'Rescue Pod',cabin:'bridge',body:'tank',legs:'spring',engine:'twin',palette:'rescue'},
 industrial:{name:'Heavy Lifter',cabin:'bridge',body:'reactor',legs:'piston',engine:'quad',palette:'rust'},
 stargazer:{name:'Stargazer',cabin:'observatory',body:'barrel',legs:'spider',engine:'ion',palette:'midnight',flame:'violet'},
 submarine:{name:'Sea of Stars',cabin:'bubble',body:'reactor',legs:'tracks',engine:'ring',palette:'ocean',flame:'mint'},
 pizzaparty:{name:'Pizza Party',cabin:'grin',body:'pizza',legs:'boots',engine:'trumpet',palette:'lemon',flame:'solar'},
 burgerjoint:{name:'Drive-through',cabin:'cool',body:'burger',legs:'tracks',engine:'triple',palette:'rescue',flame:'ember'},
 aquanaut:{name:'Fish Out of Water',cabin:'octopus',body:'aquarium',legs:'flippers',engine:'ring',palette:'ocean',flame:'mint'},
 fortress:{name:'Pocket Fortress',cabin:'castle',body:'hex',legs:'piston',engine:'bell',palette:'mono'},
 moonduck:{name:'Lunar Chicken',cabin:'chicken',body:'tank',legs:'flippers',engine:'trumpet',palette:'lemon'},
 candyfloss:{name:'Sugar Rush',cabin:'unicorn',body:'donut',legs:'boots',engine:'twin',palette:'candy',flame:'rose'}
};
export const defaultDetails=()=>({colors:{},cabinW:1,cabinH:1,bodyW:1,engineW:1,pattern:'none',flameShape:'plume',flameLength:1,flameCore:'#fff7da',flameColor:''});
export const isColor=v=>typeof v==='string'&&/^#[\da-f]{6}$/i.test(v);
export function normalDetails(value){const d=defaultDetails(),v=value&&typeof value==='object'?value:{};for(const key of ['cabinW','cabinH','bodyW','engineW','flameLength']){const limits={cabinW:[.8,1.15],cabinH:[.8,1.1],bodyW:[.9,1.12],engineW:[.8,1.12],flameLength:[.5,1.15]}[key];d[key]=Number.isFinite(v[key])?Math.max(limits[0],Math.min(limits[1],v[key])):1}for(const key of ['body','cabin','trim','glass','legs','engine','feet'])if(isColor(v.colors?.[key]))d.colors[key]=v.colors[key];if(['none','stripes','checkers','panels','dots'].includes(v.pattern))d.pattern=v.pattern;if(['plume','jet','fork','bubbles','sparks'].includes(v.flameShape))d.flameShape=v.flameShape;for(const key of ['flameCore','flameColor'])if(isColor(v[key]))d[key]=v[key];return d}
export function extraBodyShape(c){return ({reactor:'M-67 4Q-67-16 0-16Q67-16 67 4V52Q67 70 0 70Q-67 70-67 52Z',barrel:'M-53-14H53L66 2V50L53 66H-53L-66 50V2Z',hex:'M-48-15H48L75 25 48 66H-48L-75 25Z',pizza:'M-77-12L77 10 29 68H-30Z',burger:'M-72 13Q-72-20 0-20Q72-20 72 13V52Q72 68 0 68Q-72 68-72 52Z',aquarium:'M-70-14H70V66H-70Z'})[c.body]}
export function extraBodyArt(c,p){return ({reactor:`<ellipse cy="3" rx="66" ry="16" fill="${p.secondary}"/><path d="M-66 10V51M66 10V51M-44 17V57M44 17V57" stroke="${p.dark}" stroke-width="7"/><rect x="-29" y="15" width="58" height="32" rx="5" fill="${p.glass}"/><path d="M-19 25H19M-19 36H19" stroke="${p.dark}" stroke-width="3"/>`,barrel:`${[-5,11,44,59].map(y=>`<path d="M-58 ${y}H58" stroke="${p.dark}" stroke-width="5"/>`).join('')}<path d="M-40 16V40M40 16V40" stroke="${p.secondary}" stroke-width="5"/>`,hex:`<path d="M-40-6H40L61 25 40 57H-40L-61 25Z" fill="none" stroke="${p.secondary}" stroke-width="5"/><path d="M-49 17H49V37H-49Z" fill="${p.dark}" opacity=".3"/>`,pizza:`<path d="M-77-12L77 10 68 22-68 0Z" fill="#c9925b"/><path d="M-62 5L60 23 24 60H-23Z" fill="#f0ce76"/>${[[-30,15],[21,22],[0,42]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="9" fill="#bd6250"/>`).join('')}`,burger:`<path d="M-72 13Q-72-20 0-20Q72-20 72 13Z" fill="#dab06d"/><path d="M-72 20H72V29H-72Z" fill="#83a96a"/><path d="M-72 29H72V42H-72Z" fill="#755043"/><path d="M-72 42L-30 55 9 43 46 54 72 42" fill="#efce6c"/><path d="M-70 53H70Q60 68 0 68Q-60 68-70 53Z" fill="#d6a266"/>${[-35,0,35].map(x=>`<path d="M${x}-7l5 3" stroke="#f0d7a2" stroke-width="3"/>`).join('')}`,aquarium:`<rect x="-61" y="-5" width="122" height="62" rx="4" fill="${p.glass}" opacity=".55"/><path d="M-61 7Q-35-1-10 7T40 7T61 7" fill="none" stroke="#c2eeed" stroke-width="3"/><path d="M-24 33Q-8 16 9 33Q-8 50-24 33L-38 21V45Z" fill="#e8ae71"/><circle cx="3" cy="30" r="2" fill="#233b43"/><path d="M37 54Q21 35 37 23M48 54Q34 42 49 31" stroke="#7ca48e" stroke-width="4" fill="none"/><path d="M-70-14H70V-5H-70M-70 57H70V66H-70" fill="${p.secondary}"/>`})[c.body]||''}
export function cabinSurface(c){return ({cabin:'M-45-16V-65L-26-93H25L45-65V-16Z',bubble:'M-51-16V-34A51 56 0 0 1 51-34V-16Z',pod:'M-33-17L-39-69-18-101H18L39-69 33-17Z',shuttle:'M-28-12L-35-59 0-111 35-59 28-12Z',tower:'M-34-12H34L28-64H-28Z',bridge:'M-60-16V-64L-42-89H42L60-64V-16Z',observatory:'M-43-16V-48A43 43 0 0 1 43-48V-16Z',helmet:'M-42-16V-68Q-42-106 0-106Q42-106 42-68V-16Z',lantern:'M-34-18L-42-81H42L34-18Z',castle:'M-55-16V-101H-35V-82H-12V-108H12V-82H35V-101H55V-16Z'})[c.cabin]||null}
export function extraCabin(c,p,id){const shape=cabinSurface(c);const glass=`url(#${id}glass)`;if(['bridge','observatory','helmet','lantern','castle'].includes(c.cabin)){const shell=`<path d="${shape}" fill="url(#${id}metal)" stroke="#263b46" stroke-width="3"/>`;const detail={bridge:`<path d="M-45-62H-6V-39H-45ZM6-62H45V-39H6Z" fill="${glass}" stroke="#476270" stroke-width="3"/><path d="M-56-27H56" stroke="${p.primary}" stroke-width="8"/>`,observatory:`<circle cy="-62" r="31" fill="${glass}" stroke="${p.primary}" stroke-width="8"/><circle cy="-62" r="17" fill="#15384a"/><path d="M-16-75L7-75" stroke="#a9e4e6" stroke-width="3"/>`,helmet:`<path d="M-32-78Q0-94 32-78V-48Q0-35-32-48Z" fill="${glass}" stroke="${p.primary}" stroke-width="5"/><path d="M-32-27H32" stroke="${p.primary}" stroke-width="8"/>`,lantern:`<path d="M-21-81Q-30-117 0-117Q30-117 21-81" stroke="${p.dark}" stroke-width="5" fill="none"/><path d="M-30-74H30L23-29H-23Z" fill="${p.glass}"/><path d="M0-73V-30" stroke="${p.dark}" stroke-width="5"/>`,castle:`<path d="M-14-16V-43Q0-59 14-43V-16Z" fill="${glass}"/><path d="M-40-63H-27V-47H-40M27-63H40V-47H27" fill="${glass}"/><path d="M-49-76H49M-50-33H-23M23-33H50" stroke="${p.dark}" opacity=".5" stroke-width="3"/>`}[c.cabin];return shell+detail}if(c.cabin==='radar')return `<path d="M-20-14H20L12-71H-12Z" fill="url(#${id}metal)"/><path d="M0-71V-105" stroke="${p.secondary}" stroke-width="5"/><g fill="${p.glass}" stroke="${p.primary}" stroke-width="4"><path d="M-62-99H62V-70H-62Z"/><path d="M-42-99V-70M-21-99V-70M0-99V-70M21-99V-70M42-99V-70"/></g>`;return null}
export function extraLegs(c,p){const m=p.hardware||'#a8b9bf';if(!['piston','knee','tracks','flippers'].includes(c.legs))return null;let art=`<path d="M-50 43L-96 130M50 43L96 130" stroke="${m}" stroke-width="6" fill="none"/>`;if(c.legs==='piston')art+=`<path d="M-60 63L-83 105M60 63L83 105" stroke="${p.primary}" stroke-width="16"/><path d="M-67 73L-80 99M67 73L80 99" stroke="${p.secondary}" stroke-width="5"/>`;if(c.legs==='knee')art=`<path d="M-50 43L-91 75-83 105-105 135M50 43L91 75 83 105 105 135" stroke="${m}" stroke-width="8" fill="none"/><g fill="${p.primary}"><circle cx="-91" cy="75" r="9"/><circle cx="91" cy="75" r="9"/><circle cx="-83" cy="105" r="7"/><circle cx="83" cy="105" r="7"/></g>`;if(c.legs==='tracks')art+=`<g fill="#344951" stroke="${p.foot}" stroke-width="4"><rect x="-122" y="116" width="55" height="25" rx="12"/><rect x="67" y="116" width="55" height="25" rx="12"/></g>${[-108,-82,82,108].map(x=>`<circle cx="${x}" cy="128" r="7" fill="${m}"/>`).join('')}`;else if(c.legs==='flippers')art+=`<path d="M-97 121L-128 139Q-99 153-68 138L-86 122ZM97 121L128 139Q99 153 68 138L86 122Z" fill="${p.foot}" stroke="${p.dark}" stroke-width="2"/>`;else art+=`<path d="M-117 137H-81M81 137H117" stroke="${p.foot}" stroke-width="8" stroke-linecap="round"/>`;return art}
export function extraEngine(c,p,id){if(c.engine==='triple')return [-33,0,33].map(x=>`<path d="M${x-8} 65H${x+8}L${x+15} 96H${x-15}Z" fill="url(#${id}engine)" stroke="#28424d" stroke-width="2"/>`).join('');if(c.engine==='ring')return `<path d="M-40 65H40L35 91H-35Z" fill="url(#${id}engine)"/><ellipse cy="91" rx="35" ry="9" fill="${p.glass}" stroke="${p.secondary}" stroke-width="5"/><ellipse cy="91" rx="17" ry="4" fill="#29454c"/>`;if(c.engine==='trumpet')return `<path d="M-10 65H10V77Q17 87 37 91V99H-37V91Q-17 87-10 77Z" fill="${p.primary}" stroke="${p.dark}" stroke-width="2"/><path d="M-37 95H37" stroke="${p.secondary}" stroke-width="4"/>`;return null}
export function patternArt(c,p,clip){const d=c.details||defaultDetails();if(d.pattern==='none')return '';let art='';if(d.pattern==='stripes')art=Array.from({length:8},(_,i)=>`<path d="M${i*24-100}-20l-50 100" stroke="${p.secondary}" stroke-width="9"/>`).join('');if(d.pattern==='checkers')art=Array.from({length:36},(_,i)=>{const x=i%9,y=Math.floor(i/9);return (x+y)%2?`<rect x="${x*18-81}" y="${y*18-5}" width="18" height="18" fill="${p.secondary}"/>`:''}).join('');if(d.pattern==='panels')art='<path d="M-60 6H60V52H-60ZM-20 6V52M20 6V52" fill="none" stroke="'+p.secondary+'" stroke-width="3"/>';if(d.pattern==='dots')art=Array.from({length:28},(_,i)=>`<circle cx="${i%7*20-60}" cy="${Math.floor(i/7)*17}" r="4" fill="${p.secondary}"/>`).join('');return `<g clip-path="url(#${clip})" opacity=".48" pointer-events="none">${art}</g>`}
export function flamePaths(shape,w,color,gradient,core){if(shape==='jet')return `<path d="M-${w*.55} 0L0 70 ${w*.55} 0Z" fill="${gradient}"/><path d="M-4 0L0 38 4 0Z" fill="${core}"/>`;if(shape==='fork')return `<path d="M-${w} 0L-${w*.8} 65 0 26 ${w*.8} 65 ${w} 0Z" fill="${gradient}"/>`;if(shape==='bubbles')return [8,25,43,60].map((y,i)=>`<circle cy="${y}" r="${w*(1-i*.18)}" fill="${color}" opacity="${.8-i*.18}"/>`).join('');if(shape==='sparks')return [-1,0,1].map((v,i)=>`<path d="M${v*w*.6} 0l${v*5} 27m${v*5} 8l${v*3} 18" stroke="${i===1?core:color}" stroke-width="${i===1?5:3}" fill="none" stroke-linecap="round"/>`).join('');return `<path d="M-${w} 0Q-${w+8} 24 0 70Q${w+8} 24 ${w} 0Z" fill="${gradient}"/><path d="M-${w*.45} 0Q-${w*.6} 13 0 34Q${w*.6} 13 ${w*.45} 0Z" fill="${core}" opacity=".9"/>`}
